def extract_visit_markers(df, patient_ids, marker_cols):
    row_indices = df.index[df['patient_id'].isin(patient_ids)]
    selected_markers = []
    for (i, row_idx) in enumerate(row_indices):
        col = marker_cols[i % len(marker_cols)]
        selected_markers.append((row_idx, col))
    (rows, cols) = zip(*selected_markers)
    values = df.lookup(rows, cols)
    return pd.Series(values, index=rows, name='marker_value')

def calculate_employee_bonus(salary_df, bonus_tiers):
    emp_ids = salary_df.index.tolist()
    tier_cols = []
    for row in salary_df.itertuples():
        tier_cols.append(bonus_tiers[row.performance_tier])
    multipliers = salary_df.lookup(emp_ids, tier_cols)
    bonuses = salary_df['base_salary'].values * multipliers
    return pd.Series(bonuses, index=emp_ids, name='bonus_amount')

